function longestPalindromeSubsequence(text) {
  const n = text.length
  if (n === 0) return 0
  const L = Array.from({ length: n }, () => new Array(n).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    L[i][i] = 1
    for (let j = i + 1; j < n; j++) {
      L[i][j] = text[i] === text[j]
        ? (i + 1 <= j - 1 ? L[i + 1][j - 1] : 0) + 2
        : Math.max(L[i + 1][j], L[i][j - 1])
    }
  }
  return L[0][n - 1]
}

