def longest_palindrome_subsequence(text):
    n = len(text)
    if n == 0:
        return 0
    L = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        L[i][i] = 1
        for j in range(i + 1, n):
            if text[i] == text[j]:
                L[i][j] = (L[i + 1][j - 1] if i + 1 <= j - 1 else 0) + 2
            else:
                L[i][j] = max(L[i + 1][j], L[i][j - 1])
    return L[0][n - 1]
